import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process fake of the pricing downstream.
const prices = { A: 10, B: 25.5, BIG: 150, CENT: 0.99 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const create = async (items) => (await post({ items })).json()

test('POST /orders creates an order: 201, json, sequential string id, total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.deepEqual(body, { id: '1', items: [{ sku: 'A', qty: 2 }], total: 20 })
  assert.equal((await create([{ sku: 'A', qty: 1 }])).id, '2')
})

test('POST /orders prices each item through pricing, by sku', async () => {
  calls.length = 0
  await create([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }])
  assert.deepEqual(calls, ['A', 'B'])
})

test('POST /orders total is floored', async () => {
  assert.equal((await create([{ sku: 'B', qty: 1 }])).total, 25)
  assert.equal((await create([{ sku: 'CENT', qty: 1 }])).total, 0)
})

test('POST /orders: no discount at exactly 100', async () => {
  assert.equal((await create([{ sku: 'A', qty: 10 }])).total, 100)
})

test('POST /orders: 10% discount when sum is above 100, then floored', async () => {
  assert.equal((await create([{ sku: 'BIG', qty: 1 }])).total, 135)
  assert.equal((await create([{ sku: 'A', qty: 11 }])).total, 99)
})

test('POST /orders echoes items untouched, including extra fields', async () => {
  const body = await create([{ sku: 'A', qty: 1, note: 'x' }])
  assert.deepEqual(body.items, [{ sku: 'A', qty: 1, note: 'x' }])
})

test('POST /orders unknown sku: 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — pricing returns undefined, total becomes NaN, serialised as null, order still created
  const res = await post({ items: [{ sku: 'NOPE', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders missing qty: 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no qty validation, 10 * undefined = NaN
  const res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'A' }],
  ['empty body', undefined, ''],
  ['invalid JSON', undefined, '{nope'],
  ['JSON null', undefined, 'null'],
]) {
  test(`POST /orders 400 on ${name}`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('GET /orders/:id returns the stored order', async () => {
  const created = await create([{ sku: 'A', qty: 3 }])
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — a missing order returns 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

for (const [method, path] of [
  ['GET', '/orders'],
  ['GET', '/'],
  ['GET', '/nope'],
  ['GET', '/orders/1/extra'],
  ['GET', '/orders/'],
  ['POST', '/orders/1'],
  ['PUT', '/orders'],
  ['DELETE', '/orders/1'],
]) {
  test(`${method} ${path} -> 404 no route`, async () => {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  })
}
EOF
